                            </div>
                            <div className="flex-1 min-w-0">
                                <p className="text-xs font-bold text-white/80 truncate">
                                    {config.label}
                                </p>
                                {deltaText.length > 0 && (
                                    <p className="text-[10px] text-white/40">
                                        {deltaText.join(' · ')}
                                    </p>
                                )}
                            </div>
                            <span className="text-[10px] text-white/30 shrink-0">
                                {formatRelativeTime(entry.created_at)}
                            </span>
                        </motion.div>
                    )
                })}
            </div>
