'use client'

import { useState, useEffect, useRef, useCallback } from 'react'
import type { VipPayload } from '@/lib/gamification-types'
import { motion, useScroll, useTransform } from 'framer-motion'
import { QrCode, Copy, Check, Loader2, Crown, Clock } from 'lucide-react'

interface Props {
    referralCode: string | null
    referralCount: number
    vipPayload: VipPayload | null
    onLoadVip: () => Promise<VipPayload>
    onShareCopy?: () => void
}

const MILESTONES = [1, 3, 10]

function QrCodeCanvas({ value, size = 140 }: { value: string; size?: number }) {
    const canvasRef = useRef<HTMLCanvasElement>(null)

    useEffect(() => {
        const canvas = canvasRef.current
        if (!canvas) return
        const ctx = canvas.getContext('2d')
        if (!ctx) return

        const cellSize = Math.floor(size / 25)
        canvas.width = size
        canvas.height = size
        ctx.fillStyle = '#ffffff'
        ctx.fillRect(0, 0, size, size)
        ctx.fillStyle = '#0B0B0D'

        let seed = 0
        for (let i = 0; i < value.length; i++) {
            seed = ((seed << 5) - seed + value.charCodeAt(i)) | 0
        }

        const drawFinder = (x: number, y: number) => {
            for (let dy = 0; dy < 7; dy++) {
                for (let dx = 0; dx < 7; dx++) {
                    const isOuter = dy === 0 || dy === 6 || dx === 0 || dx === 6
                    const isInner = dy >= 2 && dy <= 4 && dx >= 2 && dx <= 4
                    if (isOuter || isInner) {
                        ctx.fillRect((x + dx) * cellSize, (y + dy) * cellSize, cellSize, cellSize)
                    }
                }
            }
        }

        drawFinder(1, 1)
        drawFinder(17, 1)
        drawFinder(1, 17)

        for (let y = 0; y < 25; y++) {
            for (let x = 0; x < 25; x++) {
                if (
                    (x >= 1 && x <= 7 && y >= 1 && y <= 7) ||
                    (x >= 17 && x <= 23 && y >= 1 && y <= 7) ||
                    (x >= 1 && x <= 7 && y >= 17 && y <= 23)
                ) continue
                seed = (seed * 1103515245 + 12345) & 0x7fffffff
                if (seed % 3 === 0) {
                    ctx.fillRect(x * cellSize, y * cellSize, cellSize, cellSize)
                }
            }
        }
    }, [value, size])

    return <canvas ref={canvasRef} className="rounded-xl mix-blend-multiply" style={{ width: size, height: size }} />
}

export default function VipCard({ referralCode, referralCount, vipPayload, onLoadVip, onShareCopy }: Props) {
    const [loading, setLoading] = useState(false)
    const [vip, setVip] = useState(vipPayload)
    const [codeCopied, setCodeCopied] = useState(false)
    const [refCopied, setRefCopied] = useState(false)

    // --- Scroll Reactive Lighting Setup ---
    const cardRef = useRef<HTMLDivElement>(null)
    const { scrollYProgress } = useScroll({
        target: cardRef,
        offset: ["start end", "end start"]
    })

    // Map scroll progress to glare movement (diagonally across the QR box)
    const glareX = useTransform(scrollYProgress, [0, 1], ['-150%', '250%'])
    const glareY = useTransform(scrollYProgress, [0, 1], ['-100%', '200%'])


    useEffect(() => {
        if (!vip && !loading) {
            setTimeout(() => {
                setLoading(true)
                onLoadVip().then((data) => {
                    setVip(data)
                    setLoading(false)
                }).catch(() => setLoading(false))
            }, 0)
        }
    }, [vip, loading, onLoadVip])

    const copyToClipboard = useCallback(async (text: string, type: 'code' | 'ref') => {
        await navigator.clipboard.writeText(text)
        if (type === 'code') {
            setCodeCopied(true)
            setTimeout(() => setCodeCopied(false), 2000)
        } else {
            setRefCopied(true)
            setTimeout(() => setRefCopied(false), 2000)
            onShareCopy?.()
        }
    }, [onShareCopy])

    const origin = typeof window !== 'undefined' ? window.location.origin : ''

    return (
        <div className="space-y-6" ref={cardRef}>
            {/* Title */}
            <div className="flex items-center gap-2">
                <Crown size={20} className="text-illa-yellow" fill="currentColor" />
                <h2 className="text-lg font-bold text-white">Área VIP</h2>
            </div>

            {/* Main VIP Card Container */}
            <div className="relative w-[calc(100%+1.5rem)] -ml-3 sm:w-full sm:mx-auto sm:max-w-[400px] filter drop-shadow-[0_10px_40px_rgba(0,0,0,0.8)] transition-transform hover:scale-[1.01] duration-500 perspective-1000 group rounded-[2rem] bg-[#0c0514] overflow-hidden border border-white/10">

                {/* Background Image Native Shape - Shorter height to crop empty bottom space */}
                <div className="relative w-full pt-[95%] sm:pt-[100%] bg-[#0c0514] overflow-hidden">
                    <img src="/digital-card/digitalcard-illa.webp?v=update9" alt="ILLA Exclusive Digital Card" className="absolute inset-0 w-full h-[120%] object-cover object-top pointer-events-none z-0 scale-[1.02] -translate-y-[8%]" />
                </div>

                {/* Sub-container for interactive/dynamic elements overlaying the image */}
                <div className="absolute inset-x-0 top-0 bottom-[120px] z-10 flex flex-col">

                    {/* QR Code Container - positioned over the white square on the webp art */}
                    <div className="absolute top-[37.2%] left-[51.5%] -translate-x-1/2 w-[35%] aspect-square flex items-center justify-center group/qr cursor-pointer">
                        {loading || !vip ? (
                            <div className="w-full h-full flex items-center justify-center bg-white/10 backdrop-blur-sm rounded-2xl">
                                <Loader2 size={24} className="animate-spin text-white/50" />
                            </div>
                        ) : (
                            <div className="w-full h-full flex items-center justify-center relative">
                                {/* Scroll-Reactive Glare Layer */}
                                <motion.div
                                    className="absolute inset-0 pointer-events-none z-20 mix-blend-overlay bg-gradient-to-r from-transparent via-white/80 to-transparent w-[150%] h-[150%] -rotate-45"
                                    style={{ x: glareX, y: glareY }}
                                />
                                <QrCodeCanvas value={`${origin}/vip/redeem?code=${vip.short_code}`} size={160} />
                            </div>
                        )}
                    </div>
                </div>

                {/* Bottom Area - Code & Expiration close to the CHAVE DE ACESSO text on webp art */}
                <div className="relative z-20 px-4 py-2 pb-6 flex flex-col justify-end bg-gradient-to-t from-[#0c0514] via-[#0c0514]/90 to-transparent -mt-[8rem]">
                    {/* Access Code Row */}
                    <div className="flex items-center justify-between mb-3 mt-4 px-4">
                        <span className="font-mono font-bold text-3xl tracking-[0.15em] text-white drop-shadow-md z-10">
                            {vip?.short_code ?? '••••••••'}
                        </span>
                        {vip && (
                            <button
                                onClick={() => copyToClipboard(vip.short_code, 'code')}
                                className="p-2 md:p-3 rounded-xl bg-white/5 hover:bg-white/15 border border-white/5 transition-all focus:scale-95 text-white/60 hover:text-white z-10 relative"
                                title="Copiar código"
                            >
                                {codeCopied ? <Check size={18} className="text-emerald-400" /> : <Copy size={18} />}
                            </button>
                        )}
                    </div>

                    {/* Footer Info Row */}
                    <div className="flex items-center justify-between text-[11px] md:text-xs text-white/50 px-2 relative z-10">
                        <div className="flex items-center gap-1.5 font-medium">
                            <Clock size={12} className="opacity-70" />
                            <span className="text-white/80 tracking-wide">{vip ? new Date(vip.expires_at).toLocaleDateString('pt-BR') : '--/--'}</span>
                        </div>
                        <div className="flex items-center gap-1.5 font-medium">
                            <QrCode size={12} className="opacity-70" />
                            <span>Uso presencial</span>
                        </div>
                    </div>
                </div>
            </div>

        </div>
    )
}

import { useState } from 'react'
import type { LeaderboardEntry } from '@/lib/gamification-types'
import { Trophy, Medal, ChevronRight } from 'lucide-react'
import FullRankingModal from './FullRankingModal'

interface Props {
    leaderboard: {
        top10: LeaderboardEntry[]
        user_position: number | null
    }
    currentUserId?: string
    currentUserXP?: number
}

function getRankIcon(rank: number) {
    if (rank === 1) return <Trophy size={16} className="text-illa-yellow drop-shadow-[0_2px_4px_rgba(245,158,11,0.5)]" />
    if (rank === 2) return <Medal size={16} className="text-gray-300 drop-shadow-[0_2px_4px_rgba(209,213,219,0.3)]" />
    if (rank === 3) return <Medal size={16} className="text-amber-600 drop-shadow-[0_2px_4px_rgba(217,119,6,0.3)]" />
    return <span className="text-xs font-black text-white/40 w-4 text-center">{rank}</span>
}

function getInitials(name: string | null): string {
    if (!name) return '?'
    return name.split(' ').map(w => w[0]).join('').toUpperCase().slice(0, 2)
}

export default function WeeklyLeaderboard({ leaderboard, currentUserId, currentUserXP }: Props) {
    const { top10, user_position } = leaderboard
    const [isModalOpen, setIsModalOpen] = useState(false)

    if (top10.length === 0) {
        return (
            <div className="rounded-2xl border border-dashed border-white/20 bg-white/5 p-5 text-center backdrop-blur-md">
                <Trophy size={20} className="mx-auto text-white/30 mb-1" />
                <p className="text-sm text-white/50 font-medium">Nenhuma atividade esta semana</p>
                <p className="text-xs text-white/30 mt-0.5">Complete missões para entrar no ranking!</p>
            </div>
        )
    }

    // Sync current user's XP if they are in the top 10
    const syncedTop10 = top10.map(entry => {
        if (currentUserId && entry.user_id === currentUserId && currentUserXP !== undefined) {
            return { ...entry, xp: currentUserXP }
        }
        return entry
    }).sort((a, b) => b.xp - a.xp).slice(0, 10) // Force Top 10 max

    return (
        <div className="space-y-3 relative group/ranking">
            {/* Ambient Background Glow matching Illa Exclusive */}
            <div className="absolute -inset-4 bg-gradient-to-br from-illa-pink/10 to-transparent blur-2xl pointer-events-none rounded-3xl" />

            <div className="flex items-center justify-between relative z-10">
                <h2 className="text-lg font-black text-white flex items-center gap-2 drop-shadow-md tracking-tight">
                    <Trophy size={20} className="text-illa-yellow drop-shadow-[0_0_10px_rgba(245,158,11,0.4)]" />
                    Ranking Semanal
                </h2>
                {user_position && user_position > 10 && (
                    <span className="text-xs font-bold text-white/70 bg-white/10 px-3 py-1.5 rounded-full border border-white/10 shadow-inner backdrop-blur-md shadow-black/20">
                        Você: #{user_position}
                    </span>
                )}
            </div>

            {/* Vitral Container */}
            <div className="rounded-[1.5rem] border border-white/10 bg-black/40 backdrop-blur-[20px] overflow-hidden shadow-[inset_0_1px_1px_rgba(255,255,255,0.05),0_10px_30px_rgba(0,0,0,0.5)] relative z-10 transition-colors duration-500 group-hover/ranking:border-white/20">
                {/* Surface Shine */}
                <div className="absolute inset-0 bg-gradient-to-br from-white/[0.08] to-transparent pointer-events-none" />

                <div className="relative z-10">
                    {syncedTop10.map((entry, i) => {
                        const rank = i + 1
                        const isCurrentUser = currentUserId === entry.user_id

                        return (
                            <div
                                key={entry.user_id}
                                className={`flex items-center gap-3 px-4 py-3 transition-colors ${i < syncedTop10.length - 1 ? 'border-b border-white/5' : ''
                                    } ${rank <= 3 ? 'bg-gradient-to-r from-amber-500/10 to-transparent' : 'hover:bg-white/[0.02]'
                                    }`}
                            >
                                <div className="w-6 flex justify-center flex-shrink-0">
                                    {getRankIcon(rank)}
                                </div>

                                <div className={`relative w-8 h-8 rounded-full flex items-center justify-center flex-shrink-0 border bg-gradient-to-br group ${rank === 1 ? 'from-amber-300 to-yellow-500 border-yellow-200 shadow-[0_0_10px_rgba(245,158,11,0.3)]' :
                                    rank === 2 ? 'from-gray-300 to-gray-400 border-gray-100' :
                                        rank === 3 ? 'from-amber-600 to-amber-700 border-amber-500' :
                                            'from-gray-800 to-gray-900 border-white/10'
                                    }`}>
                                    {entry.avatar_path ? (
                                        <img
                                            src={entry.avatar_path.startsWith('http')
                                                ? entry.avatar_path
                                                : `${process.env.NEXT_PUBLIC_SUPABASE_URL}/storage/v1/object/public/avatars/${entry.avatar_path}`}
                                            alt={entry.full_name || 'User'}
                                            onError={(e) => {
                                                e.currentTarget.style.display = 'none';
                                                e.currentTarget.parentElement?.classList.add('fallback-avatar');
                                            }}
                                            className="w-full h-full rounded-full object-cover shadow-inner"
                                        />
                                    ) : (
                                        <span className={`text-[10px] font-black ${rank <= 3 ? 'text-black/60' : 'text-white/50'}`}>
                                            {getInitials(entry.full_name)}
                                        </span>
                                    )}
                                    {/* Fallback Initial if image fails */}
                                    {entry.avatar_path && (
                                        <div className="hidden group-[.fallback-avatar]:flex absolute inset-0 items-center justify-center">
                                            <span className={`text-[10px] font-black ${rank <= 3 ? 'text-black/60' : 'text-white/50'}`}>
                                                {getInitials(entry.full_name)}
                                            </span>
                                        </div>
                                    )}
                                </div>

                                <div className="flex-1 min-w-0">
                                    <p className={`text-sm font-bold truncate ${isCurrentUser ? 'text-illa-pink' : 'text-white/90'}`}>
                                        {entry.full_name || 'Membro'}
                                        {isCurrentUser && <span className="ml-2 text-[8px] uppercase font-black bg-illa-pink text-white px-1 rounded-sm">Você</span>}
                                    </p>
                                </div>

                                <span className={`text-xs font-black flex-shrink-0 tabular-nums ${isCurrentUser ? 'text-white' : 'text-white/50'}`}>
                                    {entry.xp.toLocaleString('pt-BR')} XP
                                </span>
                            </div>
                        )
                    })}
                </div>

                {/* Botão Ver Ranking Completo */}
                <button
                    onClick={() => setIsModalOpen(true)}
                    className="w-full py-3.5 px-4 text-xs font-bold text-white/50 hover:text-white hover:bg-white/[0.04] transition-all flex items-center justify-center gap-1.5 uppercase tracking-wider relative z-10 border-t border-white/5 group/btn"
                >
                    Ver Ranking Completo
                    <ChevronRight size={14} strokeWidth={3} className="group-hover/btn:translate-x-1 transition-transform" />
                </button>
            </div>

            <FullRankingModal
                isOpen={isModalOpen}
                onClose={() => setIsModalOpen(false)}
                currentUserId={currentUserId}
            />
        </div>
    )
}
